<?php /* Template Name: User Profile */ get_header(); ?><section class="amia-section"><div class="amia-container amia-card"><h1>User Profile</h1><?php if ( is_user_logged_in() ) : $u = wp_get_current_user(); ?><img src="<?php echo esc_url( amia_premium_user_image( $u->ID ) ); ?>" width="140" height="140" alt=""><h2><?php echo esc_html( $u->display_name ); ?></h2><p><?php echo esc_html( $u->user_email ); ?></p><a class="amia-btn" href="<?php echo esc_url( get_edit_profile_url() ); ?>">Edit WordPress Profile</a><?php else : ?><a class="amia-btn" href="<?php echo esc_url( wp_login_url() ); ?>">Login</a><?php endif; ?></div></section><?php get_footer(); ?>
